import{_ as t,o as a,c as s,an as i}from"./chunks/framework.CqQeF48x.js";const g=JSON.parse('{"title":"Release notes convention","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/release-notes.md","filePath":"getting-started/release-notes.md","lastUpdated":null}'),n={name:"getting-started/release-notes.md"};function o(r,e,d,h,l,c){return a(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="release-notes" tabindex="-1">Release notes convention <a class="header-anchor" href="#release-notes" aria-label="Permalink to &quot;Release notes convention {#release-notes}&quot;">​</a></h1><p>Release notes live on the GitHub release, not in a file in the repository. There is no <code>NEWS.md</code> to keep in step with the tags.</p><p>The docs site reproduces them: the managed <code>docs/make.jl</code> fetches the repo&#39;s published releases when the site is built and writes them into <code>docs/src/release-notes.md</code>, newest first. Nothing is committed, so the page cannot drift from what was actually released.</p><h2 id="Writing-a-release" tabindex="-1">Writing a release <a class="header-anchor" href="#Writing-a-release" aria-label="Permalink to &quot;Writing a release {#Writing-a-release}&quot;">​</a></h2><p>TagBot opens each release body with the list of pull requests merged since the previous tag. That list is the record of what changed and needs no editing.</p><p>Add a short paragraph above it whenever the release is more than routine: what the release is for, and anything a user has to do differently because of it. A breaking change always gets one, naming what broke and what to do instead. Write it in the org&#39;s prose style, one sentence per line.</p><p>Edit the release itself when a note needs fixing. The docs page picks the change up on the next build.</p><h2 id="How-the-page-is-built" tabindex="-1">How the page is built <a class="header-anchor" href="#How-the-page-is-built" aria-label="Permalink to &quot;How the page is built {#How-the-page-is-built}&quot;">​</a></h2><p><code>EpiAwarePackageTools.DocsBuild.build_release_notes</code> reads <code>https://api.github.com/repos/OWNER/REPO/releases</code> and renders the most recent ten. Each is written under its tag as a <code>##</code> heading with its date and a link to the release; headings inside the body shift down two levels to nest under it, and TagBot&#39;s repeated title line is dropped.</p><p>The fetch is unauthenticated unless <code>GITHUB_TOKEN</code> or <code>GH_TOKEN</code> is in the environment, which CI always sets. Without one, GitHub allows 60 requests an hour per IP address, which is ample for docs builds but is the first thing to check if the page starts degrading locally.</p><p>The page never fails a build. When the releases cannot be fetched (offline, rate-limited, no API access) or the repo has no releases yet, it degrades to a short note and a link to the releases page, and the build logs why. This is the same degradation the benchmark history page uses for its <code>benchmarks</code> branch.</p><h2 id="The-page-header" tabindex="-1">The page header <a class="header-anchor" href="#The-page-header" aria-label="Permalink to &quot;The page header {#The-page-header}&quot;">​</a></h2><p><code>docs/release_notes_header.jl</code> is package-owned and holds the prose above the releases. A package with no header file gets the standard one.</p><p>A header that still mentions <code>NEWS.md</code> predates this convention: it describes a file the page no longer renders, so the build warns, names the file, and uses the standard header instead. Rewriting that one file clears the warning.</p><h2 id="Packages-with-an-existing-NEWS.md" tabindex="-1">Packages with an existing NEWS.md <a class="header-anchor" href="#Packages-with-an-existing-NEWS.md" aria-label="Permalink to &quot;Packages with an existing NEWS.md {#Packages-with-an-existing-NEWS.md}&quot;">​</a></h2><p>A <code>NEWS.md</code> already in a repository is left alone. The kit no longer seeds one, reads one, or renders one, so the file is inert. Delete it once the published releases cover its contents, or keep it as a historical record. Either way, new entries go on the release.</p>',16)])])}const u=t(n,[["render",o]]);export{g as __pageData,u as default};
